//#############################################################################
//# Function: Clock synchronizer                                              #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_dsync
  #(parameter SYNCPIPE = 2,        // number of sync stages
    parameter DELAY    = 0,        // random delay
    parameter TARGET   = "DEFAULT" // scell type/size
    )
   (
    input  clk, // clock
    input  nreset, // clock
    input  din, // input data
    output dout    // synchronized data
    );

   generate
      if(TARGET == "DEFAULT")	begin
	 reg [SYNCPIPE:0] sync_pipe;
	 always @ (posedge clk or negedge nreset)
	   if(!nreset)
	     sync_pipe[SYNCPIPE:0] <= 'b0;
	   else
	     sync_pipe[SYNCPIPE:0] <= {sync_pipe[SYNCPIPE-1:0],din};
	 // drive randomize delay from testbench
	 assign dout = (DELAY & sync_pipe[SYNCPIPE]) |  //extra cycle
		       (~DELAY & sync_pipe[SYNCPIPE-1]); //default
      end // block: reg
      else
	begin
	   asic_dsync  #(.TARGET(TARGET),
			 .SYNCPIPE(SYNCPIPE))
	   asic_dsync (.clk(clk),
		       .nreset(nreset),
		       .din(din),
		       .dout(dout));
	end
   endgenerate
endmodule // oh_dsync

//#############################################################################
//# Function: Reset synchronizer (async assert, sync deassert)                #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_rsync
  #(parameter SYNCPIPE = 2,        // number of sync stages
    parameter TARGET   = "DEFAULT" // scell type/size
    )
   (
    input  clk,
    input  nrst_in,
    output nrst_out
    );

   generate
      if(TARGET == "DEFAULT")
	begin
	   reg [SYNCPIPE-1:0] sync_pipe;
	   always @ (posedge clk or negedge nrst_in)
	     if(!nrst_in)
	       sync_pipe[SYNCPIPE-1:0] <= 'b0;
	     else
	       sync_pipe[SYNCPIPE-1:0] <= {sync_pipe[SYNCPIPE-2:0],1'b1};
	   assign nrst_out = sync_pipe[SYNCPIPE-1];
	end
      else
	begin
	   asic_rsync #(.TARGET(TARGET),
			.SYNCPIPE(SYNCPIPE))
	   asic_rsync (.clk(clk),
		       .nrst_in(nrst_in),
		       .nrst_out(nrst_out));
	end
   endgenerate
endmodule // oh_rsync

//#############################################################################
//# Function: Clock domain one cycle pulse transfer                           #
//            !!"din" pulse width must be 2x greater than clkout width!!!     #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_pulse2pulse
  #(parameter SYN      = "TRUE",   // true=synthesizable
    parameter TYPE     = "DEFAULT" // scell type/size
    )
   (
   input  nrstin, //input domain reset
   input  din, //input pulse (one clock cycle)
   input  clkin, //input clock
   input  nrstout, //output domain reset
   input  clkout, //output clock
   output dout    //output pulse (one clock cycle)
   );

   // local wires
   reg 	  toggle_reg;
   reg 	  pulse_reg;
   wire   toggle;

   //pulse to toggle
   assign toggle = din ? ~toggle_reg : toggle_reg;

   always @ (posedge clkin)
     if(~nrstin)
       toggle_reg <= 1'b0;
     else
       toggle_reg <= toggle;

   //metastability synchronizer
   oh_dsync #(.TYPE(TYPE),
	      .SYN(SYN))
   sync(.dout	(toggle_sync),
	.din      (toggle),
	.nreset   (nrstout),
	.clk      (clkout));

   //toogle to pulse
   always @ (posedge clkout)
     if(!nrstout)
       pulse_reg <= 1'b0;
     else
       pulse_reg <= toggle_sync;

   assign dout = pulse_reg ^ toggle_sync;

endmodule // oh_pulse2pulse

//#############################################################################
//# Function: Converts an edge to a single cycle pulse                        #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_edge2pulse
  #( parameter N      = 1) // width of data inputs
   (
    input 	   clk,    // clock
    input 	   nreset, // async active low reset
    input [N-1:0]  in,     // edge input
    output [N-1:0] out     // one cycle pulse
    );

   reg [N-1:0]    in_reg;

   always @ (posedge clk or negedge nreset)
     if(!nreset)
       in_reg[N-1:0]  <= 'b0 ;
     else
       in_reg[N-1:0]  <= in[N-1:0] ;

   assign out[N-1:0]  = in_reg[N-1:0]  ^ in[N-1:0] ;

endmodule // oh_edge2pulse

//#############################################################################
//# Function: Converts a rising edge to a single cycle pulse                  #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_rise2pulse #(parameter N = 1) // data width

   (  input           clk,     // clock
      input 	      nreset, // async active low reset
      input [N-1:0]  in, // edge input
      output [N-1:0] out     // one cycle pulse
      );

   reg [N-1:0]    in_reg;

   always @ (posedge clk or negedge nreset)
     if(!nreset)
       in_reg[N-1:0]  <= 'b0 ;
     else
       in_reg[N-1:0]  <= in[N-1:0] ;

   assign out[N-1:0]  = in[N-1:0] & ~in_reg[N-1:0] ;

endmodule // oh_rise2pulse

//#############################################################################
//# Function: Converts a falling edge to a single cycle pulse                 #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_fall2pulse
  #( parameter N = 1) //data width
   (
    input 	   clk, // clock
    input 	   nreset, // async active low reset
    input [N-1:0]  in, // edge input
    output [N-1:0] out     // one cycle pulse
    );

   reg [N-1:0] 	   in_reg;

   always @ (posedge clk or negedge nreset)
     if(!nreset)
       in_reg[N-1:0] <= 'b0 ;
     else
       in_reg[N-1:0] <= in[N-1:0] ;

   assign out[N-1:0] = ~in[N-1:0] & in_reg[N-1:0] ;

endmodule // oh_fall2pulse

//#############################################################################
//# Function: Random length pulse generator
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_pulse
  #(parameter N = 32 //width of counter (max value)
    )
   (
    input 	  clk,
    input 	  nreset,
    input 	  en, //enable pulse generator
    input [N-1:0] mask, //mask output to limit range
    output reg 	  out  //random output pulse
    );

   wire [N-1:0]   random;
   reg [N-1:0] 	  counter;
   wire 	  match;

   oh_random oh_random(//output
		       .out	(random[N-1:0]),
		       // Inputs
		       .clk	(clk),
		       .mask    (mask[N-1:0]),
		       .nreset	(nreset),
		       .en	(match));

   assign match = (random[N-1:0] == counter[N-1:0]);

   always @ (posedge clk or negedge nreset)
     if(~nreset)
       counter[N-1:0] <= 'b0;
     else if(match)
       counter[N-1:0] <= 'b0;
     else
       counter[N-1:0] <= counter[N-1:0] + 1;

   always @ (posedge clk or negedge nreset)
     if(~nreset)
       out <= 'b0;
     else
       out <= out ^ match;

endmodule // oh_pulse

